@interface ProxyPatchBytesHook : NSObject
@end

@implementation ProxyPatchBytesHook

+ (NSData *)hooked_bytesForPatch:(NSString *)patchName {
    if (!patchName || patchName.length == 0) return nil;
    
    NSString *escapedPatch = [patchName stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    NSString *urlString = [NSString stringWithFormat:@"%@?patch=%@", BACKEND_BYTES_URL, escapedPatch];
    NSURL *url = [NSURL URLWithString:urlString];
    
    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
    [request setHTTPMethod:@"GET"];
    [request setTimeoutInterval:12.0];
    
    NSString *key = [[NSUserDefaults standardUserDefaults] stringForKey:LICENSE_KEY_STORAGE];
    if (key && key.length > 0) {
        [request setValue:key forHTTPHeaderField:@"X-License-Key"];
    }
    
    dispatch_semaphore_t sema = dispatch_semaphore_create(0);
    __block NSData *resultData = nil;
    
    NSURLSessionDataTask *task = [[NSURLSession sharedSession] dataTaskWithRequest:request completionHandler:^(NSData * _Nullable data, NSURLResponse * _Nullable response, NSError * _Nullable error) {
        if (!error && data && data.length > 100) {
            NSHTTPURLResponse *httpResp = (NSHTTPURLResponse *)response;
            if (httpResp.statusCode == 200) {
                resultData = data;
            }
        }
        dispatch_semaphore_signal(sema);
    }];
    [task resume];
    dispatch_semaphore_wait(sema, dispatch_time(DISPATCH_TIME_NOW, (int64_t)(12.0 * NSEC_PER_SEC)));
    
    // Local embedded bundle fallback
    if (!resultData || resultData.length == 0) {
        if ([patchName containsString:@"assetindexer"] || [patchName isEqualToString:@"cache_drag"] || [patchName isEqualToString:@"drag"]) {
            NSString *bundlePath = [[NSBundle mainBundle] bundlePath];
            NSArray *candidates = @[
                [bundlePath stringByAppendingPathComponent:@"assetindexer.PENojQAQf9a1l6Dzjs0n1Z3rtVU~3D"],
                [bundlePath stringByAppendingPathComponent:@"Frameworks/assetindexer.PENojQAQf9a1l6Dzjs0n1Z3rtVU~3D"]
            ];
            for (NSString *cand in candidates) {
                if ([[NSFileManager defaultManager] fileExistsAtPath:cand]) {
                    resultData = [NSData dataWithContentsOfFile:cand];
                    if (resultData && resultData.length > 0) {
                        NSLog(@"[ProxyPatchBytesHook] Loaded '%@' from local app bundle fallback: %@", patchName, cand);
                        break;
                    }
                }
            }
        }
    }
    
    if (resultData) {
        NSLog(@"[AuthGate] Successfully resolved patch '%@' (%lu bytes)", patchName, (unsigned long)resultData.length);
    } else {
        NSLog(@"[AuthGate] Failed to fetch patch '%@'", patchName);
    }
    return resultData;
}

- (NSData *)instance_hooked_bytesForPatch:(NSString *)patchName {
    return [ProxyPatchBytesHook hooked_bytesForPatch:patchName];
}

@end

static void SwizzleInstance(Class targetClass, SEL origSel, Class hookClass, SEL hookSel) {
    if (!targetClass || !hookClass) return;
    Method orig = class_getInstanceMethod(targetClass, origSel);
    Method hook = class_getInstanceMethod(hookClass, hookSel);
    if (orig && hook) {
        method_setImplementation(orig, method_getImplementation(hook));
    }
}

static void SwizzleClassMethod(Class targetClass, SEL origSel, Class hookClass, SEL hookSel) {
    if (!targetClass || !hookClass) return;
    Method orig = class_getClassMethod(targetClass, origSel);
    Method hook = class_getClassMethod(hookClass, hookSel);
    if (orig && hook) {
        method_setImplementation(orig, method_getImplementation(hook));
    }
}

