#pragma mark - Container Detection (Methods 1 & 2)

- (FFAccessContext *)detectDirectContainerForGame:(NSString *)gameIdentifier {
    if (!gameIdentifier || gameIdentifier.length == 0) {
        gameIdentifier = [self selectedGameIdentifier];
    }
    
    NSFileManager *fm = [NSFileManager defaultManager];
    NSString *resolvedRoot = nil;
    
    // 1. Search relative app data paths (Filza / TrollStore / LiveContainer / Sandbox escapes)
    NSArray *relativePrefixes = @[
        [NSString stringWithFormat:@"_MHA_C2_AppData/%@", gameIdentifier],
        [NSString stringWithFormat:@"AppData/%@", gameIdentifier],
        [NSString stringWithFormat:@"../AppData/%@", gameIdentifier],
        [NSString stringWithFormat:@"/var/mobile/Containers/Data/Application/%@", gameIdentifier]
    ];
    for (NSString *rel in relativePrefixes) {
        BOOL isDir = NO;
        if ([fm fileExistsAtPath:rel isDirectory:&isDir] && isDir) {
            resolvedRoot = [rel stringByStandardizingPath];
            NSLog(@"[FFFileReplacementEngine] Located relative container at: %@", resolvedRoot);
            break;
        }
    }
    
    // 2. Scan /var/mobile/Containers/Data/Application/
    if (!resolvedRoot) {
        NSString *containersBase = @"/var/mobile/Containers/Data/Application";
        BOOL isDir = NO;
        if ([fm fileExistsAtPath:containersBase isDirectory:&isDir] && isDir) {
            NSError *err = nil;
            NSArray *entries = [fm contentsOfDirectoryAtPath:containersBase error:&err];
            for (NSString *uuid in entries) {
                NSString *folderPath = [containersBase stringByAppendingPathComponent:uuid];
                NSString *metaPlist = [folderPath stringByAppendingPathComponent:@".com.apple.mobile_container_manager.metadata.plist"];
                if ([fm fileExistsAtPath:metaPlist]) {
                    NSDictionary *dict = [NSDictionary dictionaryWithContentsOfFile:metaPlist];
                    NSString *ident = dict[@"MCMMetadataIdentifier"] ?: dict[@"MCMMetadataBundleID"];
                    if ([ident isEqualToString:gameIdentifier]) {
                        resolvedRoot = folderPath;
                        NSLog(@"[FFFileReplacementEngine] Found container via metadata plist: %@", resolvedRoot);
                        break;
                    }
                }
            }
        }
    }
    
    // 3. Fallback: LSApplicationWorkspace query if available
    if (!resolvedRoot) {
        id wsClass = (id)NSClassFromString(@"LSApplicationWorkspace");
        if (wsClass) {
            id ws = [wsClass performSelector:NSSelectorFromString(@"defaultWorkspace")];
            if (ws && [ws respondsToSelector:NSSelectorFromString(@"allInstalledApplications")]) {
                NSArray *apps = [ws performSelector:NSSelectorFromString(@"allInstalledApplications")];
                for (id proxy in apps) {
                    if ([proxy respondsToSelector:NSSelectorFromString(@"applicationIdentifier")] &&
                        [proxy respondsToSelector:NSSelectorFromString(@"dataContainerURL")]) {
                        NSString *appId = [proxy performSelector:NSSelectorFromString(@"applicationIdentifier")];
                        if ([appId isEqualToString:gameIdentifier]) {
                            NSURL *dataURL = [proxy performSelector:NSSelectorFromString(@"dataContainerURL")];
                            if (dataURL && dataURL.path) {
                                resolvedRoot = dataURL.path;
                                NSLog(@"[FFFileReplacementEngine] Found container via LSApplicationProxy: %@", resolvedRoot);
                                break;
                            }
                        }
                    }
                }
            }
        }
    }
    
    if (!resolvedRoot) {
        NSLog(@"[FFFileReplacementEngine] Direct container for %@ could not be located.", gameIdentifier);
        return nil;
    }
    
    NSString *bundlesSubpath = [self resolveGameAssetBundlesSubpathInContainer:resolvedRoot];
    
    FFAccessContext *ctx = [[FFAccessContext alloc] init];
    ctx.gameIdentifier = gameIdentifier;
    ctx.rootURL = [NSURL fileURLWithPath:resolvedRoot isDirectory:YES];
    ctx.assetBundlesURL = bundlesSubpath ? [NSURL fileURLWithPath:bundlesSubpath isDirectory:YES] : [NSURL fileURLWithPath:[resolvedRoot stringByAppendingPathComponent:@"Documents/contentcache/Compulsory/ios/gameassetbundles"] isDirectory:YES];
    ctx.accessMethod = 1;
    return ctx;
}

- (FFAccessContext *)beginBookmarkedFolderAccessForGame:(NSString *)gameIdentifier isStale:(BOOL *)outStale error:(NSError **)outError {
    NSString *key = [NSString stringWithFormat:@"security_scoped_game_bookmark_%@", gameIdentifier];
    NSData *bookmarkData = [[NSUserDefaults standardUserDefaults] dataForKey:key];
    if (!bookmarkData) {
        bookmarkData = [[NSUserDefaults standardUserDefaults] dataForKey:@"security_scoped_game_bookmark"];
    }
    if (!bookmarkData) {
        if (outError) {
            *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:404 userInfo:@{NSLocalizedDescriptionKey: @"No security-scoped bookmark found"}];
        }
        return nil;
    }
    
    BOOL isStale = NO;
    NSError *resError = nil;
    NSURL *resolvedURL = [NSURL URLByResolvingBookmarkData:bookmarkData
                                                   options:0
                                             relativeToURL:nil
                                       bookmarkDataIsStale:&isStale
                                                     error:&resError];
    if (outStale) *outStale = isStale;
    if (resError || !resolvedURL) {
        if (outError) *outError = resError;
        return nil;
    }
    
    [resolvedURL startAccessingSecurityScopedResource];
    
    NSString *bundlesSub = [self resolveGameAssetBundlesSubpathInContainer:resolvedURL.path];
    
    FFAccessContext *ctx = [[FFAccessContext alloc] init];
    ctx.gameIdentifier = gameIdentifier;
    ctx.rootURL = resolvedURL;
    ctx.assetBundlesURL = bundlesSub ? [NSURL fileURLWithPath:bundlesSub isDirectory:YES] : resolvedURL;
    ctx.accessMethod = 2;
    return ctx;
}

- (FFAccessContext *)resolveAccessContextForGame:(NSString *)gameIdentifier accessMethod:(int)method error:(NSError **)outError {
    if (method == 2) {
        return [self beginBookmarkedFolderAccessForGame:gameIdentifier isStale:nil error:outError];
    }
    
    FFAccessContext *ctx = [self detectDirectContainerForGame:gameIdentifier];
    if (!ctx) {
        // Fallback to bookmarked access if direct fails
        ctx = [self beginBookmarkedFolderAccessForGame:gameIdentifier isStale:nil error:nil];
    }
    return ctx;
}

#pragma mark - Multi-Candidate Path Priority Resolution (10 Subpaths)

- (NSString *)resolvedDocumentsPathForGame:(NSString *)gameId {
    FFAccessContext *ctx = [self resolveAccessContextForGame:gameId accessMethod:1 error:nil];
    if (!ctx || !ctx.rootURL) return nil;
    return [ctx.rootURL.path stringByAppendingPathComponent:@"Documents"];
}

- (NSString *)resolveGameAssetBundlesSubpathInContainer:(NSString *)containerPath {
    if (!containerPath || containerPath.length == 0) return nil;
    NSFileManager *fm = [NSFileManager defaultManager];
    
    for (NSUInteger i = 0; i < kCandidateSubpathsCount; i++) {
        NSString *candidate = [containerPath stringByAppendingPathComponent:kCandidateSubpaths[i]];
        BOOL isDir = NO;
        if ([fm fileExistsAtPath:candidate isDirectory:&isDir] && isDir) {
            return candidate;
        }
    }
    
    // Priority #1 default fallback
    return [containerPath stringByAppendingPathComponent:kCandidateSubpaths[0]];
}

