#pragma mark - Validation & Crypto

- (BOOL)validateUnityFSBundle:(NSData *)data error:(NSError **)outError {
    if (!data || data.length < 7) {
        if (outError) {
            *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:1001 userInfo:@{NSLocalizedDescriptionKey: @"The selected feature is empty or truncated"}];
        }
        return NO;
    }
    const char *bytes = (const char *)data.bytes;
    if (memcmp(bytes, "UnityFS", 7) != 0) {
        if (outError) {
            *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:1002 userInfo:@{NSLocalizedDescriptionKey: @"The selected feature is not a valid UnityFS cache bundle"}];
        }
        return NO;
    }
    return YES;
}

- (NSString *)sha256HexForData:(NSData *)data {
    if (!data || data.length == 0) return @"";
    unsigned char hash[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256(data.bytes, (CC_LONG)data.length, hash);
    NSMutableString *hex = [NSMutableString stringWithCapacity:CC_SHA256_DIGEST_LENGTH * 2];
    for (int i = 0; i < CC_SHA256_DIGEST_LENGTH; i++) {
        [hex appendFormat:@"%02x", hash[i]];
    }
    return [hex lowercaseString];
}

- (NSString *)sha256HexForFileAtPath:(NSString *)path {
    NSData *data = [NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:nil];
    return [self sha256HexForData:data];
}

#pragma mark - Core Engine Pipeline (Install & Restore)

- (BOOL)performTargetOperationForGame:(NSString *)gameId
                         accessMethod:(int)method
                      allowBackupOnly:(BOOL)backupOnly
                            operation:(void(^)(NSURL *targetURL, NSError **error))operation
                           targetPath:(NSString **)outPath
                                error:(NSError **)outError
{
    [_engineLock lock];
    @try {
        FFAccessContext *ctx = [self resolveAccessContextForGame:gameId accessMethod:method error:outError];
        if (!ctx || !ctx.assetBundlesURL) {
            if (outError && !*outError) {
                *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:404 userInfo:@{NSLocalizedDescriptionKey: @"Failed to resolve game asset bundles URL"}];
            }
            return NO;
        }
        
        NSURL *targetURL = [ctx.assetBundlesURL URLByAppendingPathComponent:BUNDLE_NAME_CACHE_RES];
        if (outPath) {
            *outPath = targetURL.path;
        }
        
        if (operation) {
            operation(targetURL, outError);
            return (outError == nil || *outError == nil);
        }
        return YES;
    } @finally {
        [_engineLock unlock];
    }
}

- (BOOL)installProfileData:(NSData *)modData
                   forGame:(NSString *)gameId
              accessMethod:(int)method
                targetPath:(NSString *)explicitPath
                     error:(NSError **)outError
{
    if (!modData || modData.length == 0) {
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:101 userInfo:@{NSLocalizedDescriptionKey: @"Mod payload is empty"}];
        return NO;
    }
    
    NSError *valErr = nil;
    if (![self validateUnityFSBundle:modData error:&valErr]) {
        if (outError) *outError = valErr;
        NSLog(@"[FFFileReplacementEngine] Install rejected: %@", valErr.localizedDescription);
        return NO;
    }
    
    NSString *targetPath = explicitPath ?: [self targetCacheResPathForGame:gameId];
    if (!targetPath) {
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:404 userInfo:@{NSLocalizedDescriptionKey: @"Target game file path could not be resolved"}];
        return NO;
    }
    
    NSFileManager *fm = [NSFileManager defaultManager];
    NSString *parentDir = [targetPath stringByDeletingLastPathComponent];
    if (![fm fileExistsAtPath:parentDir]) {
        [fm createDirectoryAtPath:parentDir withIntermediateDirectories:YES attributes:nil error:nil];
    }
    
    NSString *backupPath = [targetPath stringByAppendingString:@".fmbackup"];
    NSString *missingMarker = [targetPath stringByAppendingString:@".fmbackup.missing"];
    
    // 1. BACKUP PHASE
    if (![fm fileExistsAtPath:backupPath]) {
        if ([fm fileExistsAtPath:targetPath]) {
            NSData *origBytes = [NSData dataWithContentsOfFile:targetPath];
            if (origBytes.length > 0 && [self validateUnityFSBundle:origBytes error:nil]) {
                [origBytes writeToFile:backupPath atomically:YES];
                NSString *origHash = [self sha256HexForData:origBytes];
                NSString *bakHash = [self sha256HexForFileAtPath:backupPath];
                if (![origHash isEqualToString:bakHash]) {
                    [fm removeItemAtPath:backupPath error:nil];
                    if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:102 userInfo:@{NSLocalizedDescriptionKey: @"Backup integrity SHA256 mismatch; aborted"}];
                    return NO;
                }
                NSLog(@"[FFFileReplacementEngine] Original verified & backed up to %@", backupPath.lastPathComponent);
            } else {
                NSLog(@"[FFFileReplacementEngine] Saving raw copy to backup...");
                [fm copyItemAtPath:targetPath toPath:backupPath error:nil];
            }
        } else {
            // Target file didn't exist originally
            [@"missing" writeToFile:missingMarker atomically:YES encoding:NSUTF8StringEncoding error:nil];
            NSLog(@"[FFFileReplacementEngine] Original missing marker placed at %@", missingMarker.lastPathComponent);
        }
    } else {
        // Backup exists — verify UnityFS validity
        NSData *bakData = [NSData dataWithContentsOfFile:backupPath];
        if (![self validateUnityFSBundle:bakData error:nil]) {
            NSLog(@"[FFFileReplacementEngine] Existing backup validated.");
        }
    }
    
    // 2. WRITE PHASE (Atomic Temp Swap)
    NSString *uuid = [[NSUUID UUID] UUIDString];
    NSString *tempFile = [NSString stringWithFormat:@"%@/%@.%@.tmp", parentDir, uuid, [targetPath lastPathComponent]];
    
    if (![modData writeToFile:tempFile atomically:YES]) {
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:103 userInfo:@{NSLocalizedDescriptionKey: @"Failed to write temp mod file"}];
        return NO;
    }
    
    NSURL *tempURL = [NSURL fileURLWithPath:tempFile];
    NSURL *targetURL = [NSURL fileURLWithPath:targetPath];
    
    BOOL writeSuccess = NO;
    NSError *replaceErr = nil;
    
    if (![fm fileExistsAtPath:targetPath]) {
        writeSuccess = [fm moveItemAtURL:tempURL toURL:targetURL error:&replaceErr];
    } else {
        writeSuccess = [fm replaceItemAtURL:targetURL
                               withItemAtURL:tempURL
                              backupItemName:nil
                                     options:0
                            resultingItemURL:nil
                                       error:&replaceErr];
        if (!writeSuccess) {
            [fm removeItemAtPath:targetPath error:nil];
            writeSuccess = [fm moveItemAtURL:tempURL toURL:targetURL error:&replaceErr];
        }
    }
    
    if (!writeSuccess) {
        [fm removeItemAtPath:tempFile error:nil];
        [self restoreOriginalForGame:gameId accessMethod:method targetPath:targetPath error:nil];
        if (outError) *outError = replaceErr;
        return NO;
    }
    
    // 3. VERIFY WRITTEN FILE
    NSString *writtenHash = [self sha256HexForFileAtPath:targetPath];
    NSString *expectedHash = [self sha256HexForData:modData];
    
    if (![writtenHash isEqualToString:expectedHash]) {
        NSLog(@"[FFFileReplacementEngine] SHA256 mismatch! Expected: %@, Got: %@. Rolling back.", expectedHash, writtenHash);
        [self restoreOriginalForGame:gameId accessMethod:method targetPath:targetPath error:nil];
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:104 userInfo:@{NSLocalizedDescriptionKey: @"Integrity verification failed after write; rolled back"}];
        return NO;
    }
    
    NSLog(@"[FFFileReplacementEngine] Mod installed & verified (%lu bytes, SHA256: %@)", (unsigned long)modData.length, writtenHash);
    return YES;
}

- (BOOL)restoreOriginalForGame:(NSString *)gameId
                  accessMethod:(int)method
                    targetPath:(NSString *)explicitPath
                         error:(NSError **)outError
{
    NSString *targetPath = explicitPath ?: [self targetCacheResPathForGame:gameId];
    if (!targetPath) return NO;
    
    NSFileManager *fm = [NSFileManager defaultManager];
    NSString *backupPath = [targetPath stringByAppendingString:@".fmbackup"];
    NSString *missingMarker = [targetPath stringByAppendingString:@".fmbackup.missing"];
    
    if ([fm fileExistsAtPath:missingMarker]) {
        [fm removeItemAtPath:targetPath error:nil];
        [fm removeItemAtPath:missingMarker error:nil];
        NSLog(@"[FFFileReplacementEngine] Removed mod file with missing marker.");
        return YES;
    }
    
    if (![fm fileExistsAtPath:backupPath]) {
        NSLog(@"[FFFileReplacementEngine] Backup file not found at %@", backupPath);
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:404 userInfo:@{NSLocalizedDescriptionKey: @"Original backup state is missing"}];
        return NO;
    }
    
    NSData *backupData = [NSData dataWithContentsOfFile:backupPath];
    if (!backupData || backupData.length == 0) {
        if (outError) *outError = [NSError errorWithDomain:@"FFFileReplacementEngine" code:105 userInfo:@{NSLocalizedDescriptionKey: @"Backup data is empty"}];
        return NO;
    }
    
    NSString *parentDir = [targetPath stringByDeletingLastPathComponent];
    NSString *uuid = [[NSUUID UUID] UUIDString];
    NSString *tempFile = [NSString stringWithFormat:@"%@/%@.restore.tmp", parentDir, uuid];
    
    [backupData writeToFile:tempFile atomically:YES];
    NSURL *tempURL = [NSURL fileURLWithPath:tempFile];
    NSURL *targetURL = [NSURL fileURLWithPath:targetPath];
    
    BOOL ok = [fm replaceItemAtURL:targetURL
                     withItemAtURL:tempURL
                    backupItemName:nil
                           options:0
                  resultingItemURL:nil
                             error:nil];
    if (!ok) {
        [fm removeItemAtPath:targetPath error:nil];
        [fm moveItemAtURL:tempURL toURL:targetURL error:nil];
    }
    [fm removeItemAtPath:tempFile error:nil];
    
    NSLog(@"[FFFileReplacementEngine] Successfully restored original from %@", backupPath.lastPathComponent);
    return YES;
}

#pragma mark - High-Level Mod Operations

- (BOOL)rewriteFileWithStatus {
    NSString *gameId = [self selectedGameIdentifier];
    if (!gameId || gameId.length == 0) {
        NSLog(@"[FFFileReplacementEngine] rewriteFileWithStatus: no game identifier selected");
        return NO;
    }
    
    id espConfigClass = (id)NSClassFromString(@"ProxyESPConfig");
    if (!espConfigClass) return NO;
    
    // Check if any option 0..4 is enabled
    // Option 0 = Drag (avatar/assetindexer.PENojQAQf9a1l6Dzjs0n1Z3rtVU~3D)
    // Option 1 = 100% Body (cache_res)
    // Option 2 = 95% Body (cache_res)
    // Option 3 = Magic Bullet (cache_res)
    // Option 4 = ModChest (cache_res)
    NSInteger activeOption = -1;
    for (NSInteger opt = 0; opt < 5; opt++) {
        BOOL isEnabled = NO;
        SEL selOpt = NSSelectorFromString(@"optionEnabled:");
        if ([espConfigClass respondsToSelector:selOpt]) {
            NSMethodSignature *sig = [espConfigClass methodSignatureForSelector:selOpt];
            if (sig) {
                NSInvocation *inv = [NSInvocation invocationWithMethodSignature:sig];
                [inv setTarget:espConfigClass];
                [inv setSelector:selOpt];
                [inv setArgument:&opt atIndex:2];
                [inv invoke];
                [inv getReturnValue:&isEnabled];
            }
        }
        if (isEnabled) {
            activeOption = opt;
            break;
        }
    }
    
    if (activeOption < 0) {
        // All mod options off -> restore original cache_res AND original drag avatar
        BOOL rCache = [self forceRestoreOriginalForBundleID:gameId];
        BOOL rDrag = [self restoreDragAvatarForBundleID:gameId];
        return (rCache || rDrag);
    }
    
    if (activeOption == 0) {
        // Option 0: Drag -> applies to Documents/contentcache/Compulsory/ios/gameassetbundles/avatar/assetindexer.PENojQAQf9a1l6Dzjs0n1Z3rtVU~3D
        NSString *targetDragPath = [self targetDragAvatarPathForGame:gameId];
        if (!targetDragPath) {
            NSLog(@"[FFFileReplacementEngine] rewriteFileWithStatus: Drag avatar path for %@ not found", gameId);
            return NO;
        }
        
        // Clean up cache_res if any previous body/magic mod was applied
        [self forceRestoreOriginalForBundleID:gameId];
        
        NSData *modData = [ProxyPatchBytesHook hooked_bytesForPatch:BUNDLE_NAME_DRAG_AVATAR];
        if (!modData || modData.length == 0) {
            // Try fallback alias
            modData = [ProxyPatchBytesHook hooked_bytesForPatch:@"cache_drag"];
        }
        if (!modData || modData.length == 0) {
            NSLog(@"[FFFileReplacementEngine] Failed to fetch Drag avatar patch bytes");
            return NO;
        }
        
        NSError *err = nil;
        return [self installProfileData:modData forGame:gameId accessMethod:1 targetPath:targetDragPath error:&err];
    } else {
        // Options 1..4: Body/Magic mods -> apply to cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D
        NSString *targetCachePath = [self targetCacheResPathForGame:gameId];
        if (!targetCachePath) {
            NSLog(@"[FFFileReplacementEngine] rewriteFileWithStatus: cache_res path for %@ not found", gameId);
            return NO;
        }
        
        // Clean up drag avatar mod if previously applied
        [self restoreDragAvatarForBundleID:gameId];
        
        NSArray *patchKeys = @[@"cache_drag", @"cache_body100", @"cache_body95", @"cache_magic", @"cache_chest"];
        NSString *patchKey = (activeOption < (NSInteger)patchKeys.count) ? patchKeys[activeOption] : @"cache_body100";
        
        NSData *modData = [ProxyPatchBytesHook hooked_bytesForPatch:patchKey];
        if (!modData || modData.length == 0) {
            NSLog(@"[FFFileReplacementEngine] Failed to fetch patch bytes for key: %@", patchKey);
            return NO;
        }
        
        NSError *err = nil;
        return [self installProfileData:modData forGame:gameId accessMethod:1 targetPath:targetCachePath error:&err];
    }
}

- (BOOL)applyVisualsOption {
    NSString *gameId = [self selectedGameIdentifier];
    NSString *targetShaders = [self targetShadersPathForGame:gameId];
    if (!targetShaders) {
        NSLog(@"[FFFileReplacementEngine] applyVisualsOption: shaders path for %@ not found", gameId);
        return NO;
    }
    
    NSData *shaderData = [ProxyPatchBytesHook hooked_bytesForPatch:BUNDLE_NAME_SHADERS];
    if (!shaderData || shaderData.length == 0) {
        NSLog(@"[FFFileReplacementEngine] Failed to fetch shaders patch bytes");
        return NO;
    }
    
    NSError *err = nil;
    return [self installProfileData:shaderData forGame:gameId accessMethod:1 targetPath:targetShaders error:&err];
}

- (BOOL)restoreVisualsForBundleID:(NSString *)bundleID {
    NSString *gameId = bundleID ?: [self selectedGameIdentifier];
    NSString *targetShaders = [self targetShadersPathForGame:gameId];
    return [self restoreOriginalForGame:gameId accessMethod:1 targetPath:targetShaders error:nil];
}

- (BOOL)forceRestoreVisualsForBundleID:(NSString *)bundleID {
    return [self restoreVisualsForBundleID:bundleID];
}

- (BOOL)restoreDragAvatarForBundleID:(NSString *)bundleID {
    NSString *gameId = bundleID ?: [self selectedGameIdentifier];
    NSString *targetDrag = [self targetDragAvatarPathForGame:gameId];
    return [self restoreOriginalForGame:gameId accessMethod:1 targetPath:targetDrag error:nil];
}

- (BOOL)forceRestoreDragAvatarForBundleID:(NSString *)bundleID {
    return [self restoreDragAvatarForBundleID:bundleID];
}

- (BOOL)forceRestoreOriginalForBundleID:(NSString *)bundleID {
    NSString *gameId = bundleID ?: [self selectedGameIdentifier];
    NSString *targetCache = [self targetCacheResPathForGame:gameId];
    return [self restoreOriginalForGame:gameId accessMethod:1 targetPath:targetCache error:nil];
}

- (BOOL)restoreAllBackups {
    NSString *gameId = [self selectedGameIdentifier];
    BOOL r1 = [self forceRestoreOriginalForBundleID:gameId];
    BOOL r2 = [self restoreVisualsForBundleID:gameId];
    BOOL r3 = [self restoreDragAvatarForBundleID:gameId];
    return (r1 || r2 || r3);
}

#pragma mark - Hook Installation

+ (void)installFileReplacementHooks {
    Class espConfigClass = NSClassFromString(@"ProxyESPConfig");
    if (!espConfigClass) return;
    
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"documentsPathForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_documentsPathForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"findCacheResInDocuments:"), [ProxyESPConfigHook class], @selector(hooked_findCacheResInDocuments:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"targetFilePathForSelectedGame"), [ProxyESPConfigHook class], @selector(hooked_targetFilePathForSelectedGame));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"shadersPathForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_shadersPathForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"shadersPathForSelectedGame"), [ProxyESPConfigHook class], @selector(hooked_shadersPathForSelectedGame));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"shaderBackupPathForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_shaderBackupPathForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"dragAvatarPathForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_dragAvatarPathForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"dragAvatarPathForSelectedGame"), [ProxyESPConfigHook class], @selector(hooked_dragAvatarPathForSelectedGame));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"dragAvatarBackupPathForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_dragAvatarBackupPathForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"restoreDragAvatarForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_restoreDragAvatarForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"rewriteFileWithStatus"), [ProxyESPConfigHook class], @selector(hooked_rewriteFileWithStatus));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"rewriteFile"), [ProxyESPConfigHook class], @selector(hooked_rewriteFile));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"applyVisuals:"), [ProxyESPConfigHook class], @selector(hooked_applyVisuals:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"restoreVisualsForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_restoreVisualsForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"forceRestoreVisualsForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_forceRestoreVisualsForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"forceRestoreOriginalForBundleID:"), [ProxyESPConfigHook class], @selector(hooked_forceRestoreOriginalForBundleID:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"forceRestoreOriginalAll"), [ProxyESPConfigHook class], @selector(hooked_forceRestoreOriginalAll));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"restoreAll"), [ProxyESPConfigHook class], @selector(hooked_restoreAll));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"restoreAllBackups"), [ProxyESPConfigHook class], @selector(hooked_restoreAllBackups));
    
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"setOptionWithStatus:enabled:"), [ProxyESPConfigHook class], @selector(hooked_setOptionWithStatus:enabled:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"setOption:enabled:"), [ProxyESPConfigHook class], @selector(hooked_setOption:enabled:));
    SwizzleClassMethod(espConfigClass, NSSelectorFromString(@"lastActionResult"), [ProxyESPConfigHook class], @selector(hooked_lastActionResult));
    
    NSLog(@"[AuthGate] Robot External 4.4 File Replacement Engine swizzles installed successfully");
}

@end

#pragma mark - ProxyESPConfig Swizzle Implementation

static NSString *s_lastActionResult = @"Ready • Select a feature above";

@implementation ProxyESPConfigHook

+ (NSString *)hooked_lastActionResult {
    return s_lastActionResult ?: @"Ready • Select a feature above";
}

+ (BOOL)hooked_setOptionWithStatus:(NSInteger)option enabled:(BOOL)enabled {
    Class espClass = NSClassFromString(@"ProxyESPConfig");
    SEL selFlag = NSSelectorFromString(@"setOptionEnabledFlag:enabled:");
    if ([espClass respondsToSelector:selFlag]) {
        NSMethodSignature *sig = [espClass methodSignatureForSelector:selFlag];
        if (sig) {
            NSInvocation *inv = [NSInvocation invocationWithMethodSignature:sig];
            [inv setTarget:espClass];
            [inv setSelector:selFlag];
            [inv setArgument:&option atIndex:2];
            [inv setArgument:&enabled atIndex:3];
            [inv invoke];
        }
    }
    
    NSString *title = @"Feature";
    SEL selTitle = NSSelectorFromString(@"optionTitle:");
    if ([espClass respondsToSelector:selTitle]) {
        NSMethodSignature *sig = [espClass methodSignatureForSelector:selTitle];
        if (sig) {
            NSInvocation *inv = [NSInvocation invocationWithMethodSignature:sig];
            [inv setTarget:espClass];
            [inv setSelector:selTitle];
            [inv setArgument:&option atIndex:2];
            [inv invoke];
            void *retPtr = NULL;
            [inv getReturnValue:&retPtr];
            if (retPtr) {
                title = (__bridge NSString *)retPtr;
            }
        }
    }
    
    if (option == 5) {
        [[FFFileReplacementEngine sharedEngine] applyVisualsOption];
    } else {
        [[FFFileReplacementEngine sharedEngine] rewriteFileWithStatus];
    }
    
    if (enabled) {
        s_lastActionResult = [NSString stringWithFormat:@"%@ applied", title];
    } else {
        s_lastActionResult = [NSString stringWithFormat:@"%@ reverted", title];
    }
    
    [VIPThemeManager updateLiveStatusLabelInActiveView];
    return YES;
}

+ (void)hooked_setOption:(NSInteger)option enabled:(BOOL)enabled {
    [ProxyESPConfigHook hooked_setOptionWithStatus:option enabled:enabled];
}

