#pragma mark - Unified VIP Dark Theme Engine

@interface VIPThemeManager : NSObject
+ (UIColor *)colorObsidianBg;
+ (UIColor *)colorCardSlate;
+ (UIColor *)colorCardBorder;
+ (UIColor *)colorAccentBlue;
+ (UIColor *)colorCyanHighlight;
+ (UIColor *)colorTextPrimary;
+ (UIColor *)colorTextSecondary;
+ (UIColor *)colorInputContainer;
+ (void)applyVIPThemeToViewController:(UIViewController *)vc;
+ (void)applyVIPThemeToView:(UIView *)rootView;
+ (void)applyVIPThemeToTabBar:(UITabBar *)tabBar;
+ (void)applyVIPThemeToImGuiMenu:(UIView *)menuView;
+ (void)removeModChestFromViewController:(UIViewController *)vc;
+ (void)updateLiveStatusLabelInActiveView;
+ (void)installThemeHooks;
@end

@implementation VIPThemeManager

+ (UIColor *)colorObsidianBg {
    return [UIColor colorWithRed:0.06 green:0.07 blue:0.09 alpha:0.98];
}

+ (UIColor *)colorCardSlate {
    return [UIColor colorWithRed:0.11 green:0.13 blue:0.18 alpha:0.95];
}

+ (UIColor *)colorCardBorder {
    return [UIColor colorWithRed:0.22 green:0.28 blue:0.40 alpha:0.60];
}

+ (UIColor *)colorAccentBlue {
    return [UIColor colorWithRed:0.20 green:0.50 blue:0.95 alpha:1.0];
}

+ (UIColor *)colorCyanHighlight {
    return [UIColor colorWithRed:0.35 green:0.65 blue:1.0 alpha:1.0];
}

+ (UIColor *)colorTextPrimary {
    return [UIColor whiteColor];
}

+ (UIColor *)colorTextSecondary {
    return [UIColor colorWithRed:0.60 green:0.65 blue:0.75 alpha:1.0];
}

+ (UIColor *)colorInputContainer {
    return [UIColor colorWithRed:0.07 green:0.08 blue:0.12 alpha:0.95];
}

+ (void)applyVIPThemeToViewController:(UIViewController *)vc {
    if (!vc || !vc.isViewLoaded) return;
    
    if (@available(iOS 13.0, *)) {
        vc.overrideUserInterfaceStyle = UIUserInterfaceStyleDark;
    }
    
    // Setup Dark Background
    vc.view.backgroundColor = [self colorObsidianBg];
    
    // Check if background gradient already added
    BOOL hasGradient = NO;
    for (CALayer *sub in vc.view.layer.sublayers) {
        if ([sub isKindOfClass:[CAGradientLayer class]] && [sub.name isEqualToString:@"VIPGradient"]) {
            hasGradient = YES;
            sub.frame = vc.view.bounds;
            break;
        }
    }
    
    if (!hasGradient) {
        CAGradientLayer *gradient = [CAGradientLayer layer];
        gradient.name = @"VIPGradient";
        gradient.frame = vc.view.bounds;
        gradient.colors = @[
            (id)[UIColor colorWithRed:0.08 green:0.12 blue:0.20 alpha:1.0].CGColor,
            (id)[UIColor colorWithRed:0.04 green:0.05 blue:0.07 alpha:1.0].CGColor
        ];
        gradient.startPoint = CGPointMake(0.5, 0.0);
        gradient.endPoint = CGPointMake(0.5, 1.0);
        [vc.view.layer insertSublayer:gradient atIndex:0];
    }
    
    // Recursively theme all child elements
    [self applyVIPThemeToView:vc.view];
    
    // Apply tab and navigation bar titles
    NSString *className = NSStringFromClass([vc class]);
    if ([className containsString:@"NoExploit"]) {
        vc.title = @"Mods";
        vc.navigationItem.title = @"Mods";
        if (vc.tabBarItem) {
            vc.tabBarItem.title = @"Mods";
        }
    } else if ([className containsString:@"Exploit"]) {
        vc.title = @"Home";
        vc.navigationItem.title = @"Home";
        if (vc.tabBarItem) {
            vc.tabBarItem.title = @"Home";
        }
    }
    
    if (vc.tabBarController) {
        [self applyVIPThemeToTabBar:vc.tabBarController.tabBar];
    }
    if (vc.navigationController) {
        vc.navigationController.navigationBar.barTintColor = [self colorObsidianBg];
        vc.navigationController.navigationBar.tintColor = [self colorAccentBlue];
        vc.navigationController.navigationBar.titleTextAttributes = @{
            NSForegroundColorAttributeName: [self colorTextPrimary],
            NSFontAttributeName: [UIFont boldSystemFontOfSize:18.0]
        };
    }
}

+ (void)applyVIPThemeToView:(UIView *)rootView {
    if (!rootView) return;
    
    for (UIView *subview in rootView.subviews) {
        // 1. UISegmentedControl
        if ([subview isKindOfClass:[UISegmentedControl class]]) {
            UISegmentedControl *seg = (UISegmentedControl *)subview;
            seg.backgroundColor = [self colorInputContainer];
            if (@available(iOS 13.0, *)) {
                seg.selectedSegmentTintColor = [self colorAccentBlue];
            }
            seg.layer.cornerRadius = 10.0;
            seg.layer.borderWidth = 1.0;
            seg.layer.borderColor = [self colorCardBorder].CGColor;
            seg.clipsToBounds = YES;
            
            [seg setTitleTextAttributes:@{
                NSForegroundColorAttributeName: [self colorTextSecondary],
                NSFontAttributeName: [UIFont systemFontOfSize:13.0]
            } forState:UIControlStateNormal];
            
            [seg setTitleTextAttributes:@{
                NSForegroundColorAttributeName: [self colorTextPrimary],
                NSFontAttributeName: [UIFont boldSystemFontOfSize:13.0]
            } forState:UIControlStateSelected];
            continue;
        }
        
        // 2. UISwitch
        if ([subview isKindOfClass:[UISwitch class]]) {
            UISwitch *sw = (UISwitch *)subview;
            sw.onTintColor = [self colorAccentBlue];
            sw.thumbTintColor = [UIColor whiteColor];
            continue;
        }
        
        // 3. UIButton
        if ([subview isKindOfClass:[UIButton class]]) {
            UIButton *btn = (UIButton *)subview;
            NSString *title = [btn titleForState:UIControlStateNormal];
            
            if ([title isEqualToString:@"STOP"] || [title isEqualToString:@"START"]) {
                btn.backgroundColor = [self colorAccentBlue];
                [btn setTitleColor:[self colorTextPrimary] forState:UIControlStateNormal];
                btn.layer.cornerRadius = 10.0;
                btn.layer.shadowColor = [self colorAccentBlue].CGColor;
                btn.layer.shadowOffset = CGSizeMake(0, 3);
                btn.layer.shadowRadius = 8.0;
                btn.layer.shadowOpacity = 0.5;
            } else if ([title isEqualToString:@"Reset"] || [title containsString:@"Reset"]) {
                btn.backgroundColor = [self colorCardSlate];
                [btn setTitleColor:[self colorCyanHighlight] forState:UIControlStateNormal];
                btn.layer.cornerRadius = 10.0;
                btn.layer.borderWidth = 1.0;
                btn.layer.borderColor = [self colorCardBorder].CGColor;
            }
            continue;
        }
        
        // 4. UILabel
        if ([subview isKindOfClass:[UILabel class]]) {
            UILabel *lbl = (UILabel *)subview;
            NSString *txt = lbl.text;
            if (txt && (
                [txt containsString:@"sandbox escaped"] ||
                [txt containsString:@"patch bytes"] ||
                [txt containsString:@"unavailable"] ||
                [txt containsString:@"server/key"] ||
                [txt containsString:@"Enter your"]
            )) {
                lbl.textColor = [self colorTextSecondary];
            } else if (txt && (
                [txt containsString:@"applied"] ||
                [txt containsString:@"reverted"] ||
                [txt containsString:@"reset"] ||
                [txt containsString:@"Select"] ||
                [txt containsString:@"Ready"] ||
                [txt containsString:@"Active"]
            )) {
                lbl.textColor = [self colorCyanHighlight];
                lbl.font = [UIFont boldSystemFontOfSize:13.5];
                lbl.textAlignment = NSTextAlignmentCenter;
            } else {
                lbl.textColor = [self colorTextPrimary];
            }
            continue;
        }
        
        // 5. Card Containers / Row Boxes
        if (subview.layer.cornerRadius > 0 && subview != rootView) {
            subview.backgroundColor = [self colorCardSlate];
            subview.layer.borderColor = [self colorCardBorder].CGColor;
            subview.layer.borderWidth = 1.0;
            subview.layer.shadowColor = [UIColor blackColor].CGColor;
            subview.layer.shadowOffset = CGSizeMake(0, 4);
            subview.layer.shadowRadius = 8.0;
            subview.layer.shadowOpacity = 0.35;
        }
        
        // Check for ImGui floating menu classes
        NSString *clsName = NSStringFromClass([subview class]);
        if ([clsName containsString:@"MenuUIView"] || [clsName containsString:@"MenuView"]) {
            [self applyVIPThemeToImGuiMenu:subview];
        }
        
        // Recurse down hierarchy
        [self applyVIPThemeToView:subview];
    }
}

+ (void)applyVIPThemeToTabBar:(UITabBar *)tabBar {
    if (!tabBar) return;
    
    // Rename tab items to Home, Mods, and ensure Account is preserved
    if (tabBar.items.count >= 3) {
        if ([tabBar.items[0].title isEqualToString:@"Exploit"] || tabBar.items[0].title.length == 0) {
            tabBar.items[0].title = @"Home";
        }
        if ([tabBar.items[1].title isEqualToString:@"No Exploit"] || tabBar.items[1].title.length == 0) {
            tabBar.items[1].title = @"Mods";
        }
        if (tabBar.items[2].title.length == 0 || [tabBar.items[2].title isEqualToString:@"Account"]) {
            tabBar.items[2].title = @"Account";
        }
    }
    
    tabBar.barTintColor = [self colorObsidianBg];
    tabBar.backgroundColor = [self colorObsidianBg];
    tabBar.tintColor = [self colorAccentBlue];
    tabBar.unselectedItemTintColor = [self colorTextSecondary];
    
    if (@available(iOS 13.0, *)) {
        UITabBarAppearance *appearance = [[UITabBarAppearance alloc] init];
        [appearance configureWithOpaqueBackground];
        appearance.backgroundColor = [self colorObsidianBg];
        
        appearance.stackedLayoutAppearance.selected.iconColor = [self colorAccentBlue];
        appearance.stackedLayoutAppearance.selected.titleTextAttributes = @{
            NSForegroundColorAttributeName: [self colorAccentBlue],
            NSFontAttributeName: [UIFont boldSystemFontOfSize:11.0]
        };
        appearance.stackedLayoutAppearance.normal.iconColor = [self colorTextSecondary];
        appearance.stackedLayoutAppearance.normal.titleTextAttributes = @{
            NSForegroundColorAttributeName: [self colorTextSecondary],
            NSFontAttributeName: [UIFont systemFontOfSize:11.0]
        };
        
        tabBar.standardAppearance = appearance;
        if (@available(iOS 15.0, *)) {
            tabBar.scrollEdgeAppearance = appearance;
        }
    }
}

+ (void)applyVIPThemeToImGuiMenu:(UIView *)menuView {
    if (!menuView) return;
    
    menuView.backgroundColor = [self colorCardSlate];
    menuView.layer.cornerRadius = 16.0;
    menuView.layer.borderWidth = 1.0;
    menuView.layer.borderColor = [self colorCardBorder].CGColor;
    menuView.layer.shadowColor = [UIColor blackColor].CGColor;
    menuView.layer.shadowOffset = CGSizeMake(0, 8);
    menuView.layer.shadowRadius = 16.0;
    menuView.layer.shadowOpacity = 0.6;
    
    // Style all child components of ImGui HUD
    for (UIView *child in menuView.subviews) {
        if ([child isKindOfClass:[UILabel class]]) {
            ((UILabel *)child).textColor = [self colorTextPrimary];
        } else if ([child isKindOfClass:[UISwitch class]]) {
            ((UISwitch *)child).onTintColor = [self colorAccentBlue];
        } else if ([child isKindOfClass:[UISlider class]]) {
            UISlider *sl = (UISlider *)child;
            sl.minimumTrackTintColor = [self colorAccentBlue];
            sl.thumbTintColor = [UIColor whiteColor];
        }
    }
}

+ (void)updateLiveStatusLabelInActiveView {
    dispatch_async(dispatch_get_main_queue(), ^{
        UIWindow *window = GetActiveAppWindow();
        if (!window) return;
        
        UIViewController *rootVC = window.rootViewController;
        NSMutableArray<UIViewController *> *vcList = [NSMutableArray array];
        if (rootVC) [vcList addObject:rootVC];
        if (rootVC.presentedViewController) [vcList addObject:rootVC.presentedViewController];
        if ([rootVC isKindOfClass:[UITabBarController class]]) {
            UITabBarController *tab = (UITabBarController *)rootVC;
            if (tab.viewControllers) [vcList addObjectsFromArray:tab.viewControllers];
            if (tab.selectedViewController) [vcList addObject:tab.selectedViewController];
        }
        
        NSString *statusText = [ProxyESPConfigHook hooked_lastActionResult];
        
        for (UIViewController *vc in vcList) {
            NSString *className = NSStringFromClass([vc class]);
            if ([className containsString:@"Exploit"] || [className containsString:@"Root"]) {
                UILabel *resLbl = nil;
                if ([vc respondsToSelector:NSSelectorFromString(@"resultLabel")]) {
                    resLbl = (UILabel *)[vc valueForKey:@"resultLabel"];
                }
                if (!resLbl && [vc respondsToSelector:NSSelectorFromString(@"statusLabel")]) {
                    resLbl = (UILabel *)[vc valueForKey:@"statusLabel"];
                }
                if (resLbl) {
                    resLbl.text = statusText;
                    resLbl.textColor = [VIPThemeManager colorCyanHighlight];
                    resLbl.font = [UIFont boldSystemFontOfSize:13.5];
                    resLbl.textAlignment = NSTextAlignmentCenter;
                    resLbl.numberOfLines = 0;
                    resLbl.hidden = NO;
                    resLbl.alpha = 1.0;
                }
                
                // Also traverse scrollView subviews
                UIScrollView *sv = nil;
                if ([vc respondsToSelector:NSSelectorFromString(@"scrollView")]) {
                    sv = (UIScrollView *)[vc valueForKey:@"scrollView"];
                }
                if (sv) {
                    for (UIView *sub in sv.subviews) {
                        if ([sub isKindOfClass:[UILabel class]]) {
                            UILabel *lbl = (UILabel *)sub;
                            if (lbl.frame.origin.y > 350.0 &&
                                ![lbl.text isEqualToString:@"Drag"] &&
                                ![lbl.text isEqualToString:@"100% Body"] &&
                                ![lbl.text isEqualToString:@"95% Body"] &&
                                ![lbl.text isEqualToString:@"Maggic Bullet"] &&
                                ![lbl.text isEqualToString:@"ModChest"]) {
                                lbl.text = statusText;
                                lbl.textColor = [VIPThemeManager colorCyanHighlight];
                                lbl.font = [UIFont boldSystemFontOfSize:13.5];
                                lbl.textAlignment = NSTextAlignmentCenter;
                                lbl.numberOfLines = 0;
                                lbl.hidden = NO;
                                lbl.alpha = 1.0;
                            }
                        }
                    }
                }
            }
        }
    });
}

+ (void)removeModChestFromViewController:(UIViewController *)vc {
    if (!vc || !vc.isViewLoaded) return;
    
    // Only process Exploit / NoExploit VCs
    NSString *className = NSStringFromClass([vc class]);
    if (![className containsString:@"Exploit"]) return;
    
    // Find the scroll view (first UIScrollView child)
    UIScrollView *scrollView = nil;
    for (UIView *child in vc.view.subviews) {
        if ([child isKindOfClass:[UIScrollView class]]) {
            scrollView = (UIScrollView *)child;
            break;
        }
    }
    if (!scrollView) return;
    
    // The ModChest row lives inside aimContainer (or directly in scrollView)
    UIView *modChestRow = nil;
    UIView *modChestParent = nil;
    CGFloat rowHeight = 0;
    
    NSMutableArray<UIView *> *queue = [NSMutableArray arrayWithObject:scrollView];
    while (queue.count > 0 && !modChestRow) {
        UIView *parent = queue.firstObject;
        [queue removeObjectAtIndex:0];
        
        for (UIView *child in parent.subviews) {
            if (child.hidden) continue;
            for (UIView *sub in child.subviews) {
                if ([sub isKindOfClass:[UILabel class]]) {
                    UILabel *lbl = (UILabel *)sub;
                    if ([lbl.text isEqualToString:@"ModChest"]) {
                        modChestRow = child;
                        modChestParent = parent;
                        rowHeight = child.frame.size.height + 8.0;
                        break;
                    }
                }
            }
            if (modChestRow) break;
            if (![child isKindOfClass:[UILabel class]] &&
                ![child isKindOfClass:[UIButton class]] &&
                ![child isKindOfClass:[UISwitch class]] &&
                child.subviews.count > 0) {
                [queue addObject:child];
            }
        }
    }
    
    if (modChestRow) {
        CGFloat modChestY = modChestRow.frame.origin.y;
        modChestRow.hidden = YES;
        [modChestRow removeFromSuperview];
        
        if (modChestParent && modChestParent != scrollView) {
            for (UIView *sibling in modChestParent.subviews) {
                if (sibling.hidden) continue;
                if (sibling.frame.origin.y > modChestY) {
                    CGRect f = sibling.frame;
                    f.origin.y -= rowHeight;
                    sibling.frame = f;
                }
            }
        }
    }
    
    // Find Reset button & Result/Status label
    UIButton *resetButton = nil;
    UILabel *resultLabel = nil;
    
    for (UIView *child in scrollView.subviews) {
        if ([child isKindOfClass:[UIButton class]]) {
            UIButton *btn = (UIButton *)child;
            NSString *title = [btn titleForState:UIControlStateNormal];
            if ([title containsString:@"Reset"] || [btn.currentTitle containsString:@"Reset"]) {
                resetButton = btn;
            }
        } else if ([child isKindOfClass:[UILabel class]]) {
            UILabel *lbl = (UILabel *)child;
            if (lbl != modChestRow) {
                resultLabel = lbl;
            }
        }
    }
    
    UIView *activeContainer = nil;
    if ([vc respondsToSelector:NSSelectorFromString(@"aimContainer")]) {
        activeContainer = [vc valueForKey:@"aimContainer"];
    }
    
    CGFloat nextY = 460.0;
    if (activeContainer && activeContainer.superview == scrollView) {
        nextY = activeContainer.frame.origin.y + activeContainer.frame.size.height + 16.0;
    }
    
    CGFloat screenW = scrollView.bounds.size.width > 0 ? scrollView.bounds.size.width : [UIScreen mainScreen].bounds.size.width;
    CGFloat cardW = screenW - 32.0;
    
    if (resetButton) {
        resetButton.frame = CGRectMake(16.0, nextY, cardW, 44.0);
        nextY += 44.0 + 14.0;
    }
    
    if (!resultLabel && [vc respondsToSelector:NSSelectorFromString(@"resultLabel")]) {
        resultLabel = [vc valueForKey:@"resultLabel"];
    }
    if (!resultLabel && [vc respondsToSelector:NSSelectorFromString(@"statusLabel")]) {
        resultLabel = [vc valueForKey:@"statusLabel"];
    }
    
    if (resultLabel) {
        resultLabel.frame = CGRectMake(16.0, nextY, cardW, 44.0);
        resultLabel.hidden = NO;
        resultLabel.alpha = 1.0;
        resultLabel.textColor = [VIPThemeManager colorCyanHighlight];
        resultLabel.textAlignment = NSTextAlignmentCenter;
        resultLabel.font = [UIFont boldSystemFontOfSize:14.0];
        resultLabel.numberOfLines = 0;
        if (!resultLabel.text || resultLabel.text.length == 0 || [resultLabel.text isEqualToString:@"Select an option above"]) {
            resultLabel.text = [ProxyESPConfigHook hooked_lastActionResult];
        }
        nextY += 44.0 + 20.0;
    }
    
    scrollView.contentSize = CGSizeMake(screenW, nextY + 40.0);
}

+ (void)installThemeHooks {
    // 1. Enforce proxy.theme.mode = @"dark" in NSUserDefaults
    [[NSUserDefaults standardUserDefaults] setObject:@"dark" forKey:@"proxy.theme.mode"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    
    [[NSNotificationCenter defaultCenter] postNotificationName:@"proxy.theme.changed" object:nil];
    
    // 2. Swizzle UIViewController viewWillAppear:
    Class vcClass = [UIViewController class];
    Method origMethod = class_getInstanceMethod(vcClass, @selector(viewWillAppear:));
    
    void (*orig_viewWillAppear)(id, SEL, BOOL) = (void (*)(id, SEL, BOOL))method_getImplementation(origMethod);
    
    IMP custom_viewWillAppear = imp_implementationWithBlock(^(id self, BOOL animated) {
        orig_viewWillAppear(self, @selector(viewWillAppear:), animated);
        
        NSString *className = NSStringFromClass([self class]);
        if ([className containsString:@"Exploit"] ||
            [className containsString:@"RootViewController"] ||
            [className containsString:@"HUD"] ||
            [className containsString:@"Proxy"]) {
            [VIPThemeManager applyVIPThemeToViewController:(UIViewController *)self];
            [VIPThemeManager removeModChestFromViewController:(UIViewController *)self];
            [VIPThemeManager updateLiveStatusLabelInActiveView];
        }
    });
    
    method_setImplementation(origMethod, custom_viewWillAppear);
    
    // 3. Strict Portrait Orientation Enforcement Across All ViewControllers
    Method origOrient = class_getInstanceMethod(vcClass, @selector(supportedInterfaceOrientations));
    if (origOrient) {
        IMP custom_supportedOrientations = imp_implementationWithBlock(^(id self) {
            return (UIInterfaceOrientationMask)UIInterfaceOrientationMaskPortrait;
        });
        method_setImplementation(origOrient, custom_supportedOrientations);
    }
    
    Method origRotate = class_getInstanceMethod(vcClass, @selector(shouldAutorotate));
    if (origRotate) {
        IMP custom_shouldAutorotate = imp_implementationWithBlock(^(id self) {
            return NO;
        });
        method_setImplementation(origRotate, custom_shouldAutorotate);
    }
    
    // 4. Hook switchChanged / refreshStatus / resetTapped / restoreTapped on Exploit ViewControllers
    for (NSString *cName in @[@"ProxyExploitViewController", @"ProxyNoExploitViewController"]) {
        Class c = NSClassFromString(cName);
        if (!c) continue;
        
        SEL selRefresh = NSSelectorFromString(@"refreshStatus");
        Method mRefresh = class_getInstanceMethod(c, selRefresh);
        if (mRefresh) {
            void (*orig_refresh)(id, SEL) = (void (*)(id, SEL))method_getImplementation(mRefresh);
            IMP custom_refresh = imp_implementationWithBlock(^(id self) {
                orig_refresh(self, selRefresh);
                [VIPThemeManager updateLiveStatusLabelInActiveView];
            });
            method_setImplementation(mRefresh, custom_refresh);
        }
        
        SEL selSwitch = NSSelectorFromString(@"switchChanged:");
        Method mSwitch = class_getInstanceMethod(c, selSwitch);
        if (mSwitch) {
            void (*orig_switch)(id, SEL, id) = (void (*)(id, SEL, id))method_getImplementation(mSwitch);
            IMP custom_switch = imp_implementationWithBlock(^(id self, id sw) {
                orig_switch(self, selSwitch, sw);
                [VIPThemeManager updateLiveStatusLabelInActiveView];
            });
            method_setImplementation(mSwitch, custom_switch);
        }
        
        SEL selReset = NSSelectorFromString(@"resetTapped");
        Method mReset = class_getInstanceMethod(c, selReset);
        if (mReset) {
            void (*orig_reset)(id, SEL) = (void (*)(id, SEL))method_getImplementation(mReset);
            IMP custom_reset = imp_implementationWithBlock(^(id self) {
                orig_reset(self, selReset);
                s_lastActionResult = @"reset done";
                [VIPThemeManager updateLiveStatusLabelInActiveView];
            });
            method_setImplementation(mReset, custom_reset);
        }
        
        SEL selRestore = NSSelectorFromString(@"restoreTapped");
        Method mRestore = class_getInstanceMethod(c, selRestore);
        if (mRestore) {
            void (*orig_restore)(id, SEL) = (void (*)(id, SEL))method_getImplementation(mRestore);
            IMP custom_restore = imp_implementationWithBlock(^(id self) {
                orig_restore(self, selRestore);
                s_lastActionResult = @"reset done";
                [VIPThemeManager updateLiveStatusLabelInActiveView];
            });
            method_setImplementation(mRestore, custom_restore);
        }
    }
    
    NSLog(@"[AuthGate] VIP Dark Theme Engine & Strict Portrait Locks successfully installed");
}

@end

static UIWindow *GetActiveAppWindow(void) {
    UIWindow *window = nil;
    if (@available(iOS 13.0, *)) {
        for (UIScene *scene in [UIApplication sharedApplication].connectedScenes) {
            if ([scene isKindOfClass:[UIWindowScene class]] && scene.activationState == UISceneActivationStateForegroundActive) {
                for (UIWindow *w in ((UIWindowScene *)scene).windows) {
                    if (w.isKeyWindow) {
                        window = w;
                        break;
                    }
                }
            }
            if (window) break;
        }
    }
    if (!window) {
        window = [UIApplication sharedApplication].windows.firstObject;
    }
    return window;
}

