- (void)openDiscordLink {
    NSURL *url = [NSURL URLWithString:DISCORD_INVITE_URL];
    if ([[UIApplication sharedApplication] canOpenURL:url]) {
        if (@available(iOS 10.0, *)) {
            [[UIApplication sharedApplication] openURL:url options:@{} completionHandler:nil];
        } else {
            [[UIApplication sharedApplication] openURL:url];
        }
    }
}

- (void)pasteTapped:(id)sender {
    UIPasteboard *pasteboard = [UIPasteboard generalPasteboard];
    if (pasteboard.string && pasteboard.string.length > 0) {
        self.keyField.text = [pasteboard.string stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
        [self updateStatus:@"Key pasted from clipboard." isError:NO];
    } else {
        [self updateStatus:@"Clipboard is empty." isError:YES];
    }
}

- (BOOL)textFieldShouldReturn:(UITextField *)textField {
    [textField resignFirstResponder];
    [self activateTapped:nil];
    return YES;
}

- (void)activateTapped:(id)sender {
    [self.view endEditing:YES];
    
    NSString *rawKey = self.keyField.text;
    NSString *trimmedKey = [rawKey stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    
    if (!trimmedKey || trimmedKey.length == 0) {
        [self updateStatus:@"Please enter your license key." isError:YES];
        return;
    }
    
    [self validateKeyWithServer:trimmedKey isAutoLogin:NO];
}

#pragma mark - Server Authentication Engine

- (void)setLoading:(BOOL)loading {
    if (loading) {
        [self.spinner startAnimating];
        self.activateButton.enabled = NO;
        self.activateButton.alpha = 0.8;
    } else {
        [self.spinner stopAnimating];
        self.activateButton.enabled = YES;
        self.activateButton.alpha = 1.0;
    }
}

- (void)updateStatus:(NSString *)message isError:(BOOL)isError {
    dispatch_async(dispatch_get_main_queue(), ^{
        self.statusLabel.text = message;
        if (isError) {
            self.statusLabel.textColor = [UIColor colorWithRed:1.0 green:0.35 blue:0.35 alpha:1.0];
        } else {
            self.statusLabel.textColor = [UIColor colorWithRed:0.35 green:0.85 blue:0.45 alpha:1.0];
        }
    });
}

- (void)validateKeyWithServer:(NSString *)key isAutoLogin:(BOOL)isAutoLogin {
    [self setLoading:YES];
    [self updateStatus:isAutoLogin ? @"Verifying saved license..." : @"Validating with authentication server..." isError:NO];
    
    NSString *udid = [[[UIDevice currentDevice] identifierForVendor] UUIDString] ?: @"IOS-DEVICE-1";
    NSString *appVer = [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"] ?: @"1.1";
    NSString *escapedKey = [key stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    NSString *escapedUdid = [udid stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    NSString *escapedVer = [appVer stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    
    NSString *urlString = [NSString stringWithFormat:@"%@?license_key=%@&udid=%@&version=%@", BACKEND_SERVER_URL, escapedKey, escapedUdid, escapedVer];
    NSURL *url = [NSURL URLWithString:urlString];
    
    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
    [request setHTTPMethod:@"GET"];
    [request setTimeoutInterval:10.0];
    
    NSURLSessionDataTask *task = [[NSURLSession sharedSession] dataTaskWithRequest:request completionHandler:^(NSData * _Nullable data, NSURLResponse * _Nullable response, NSError * _Nullable error) {
        dispatch_async(dispatch_get_main_queue(), ^{
            [self setLoading:NO];
            
            if (error != nil || data == nil) {
                [self updateStatus:@"Server unreachable. Please check your connection." isError:YES];
                return;
            }
            
            NSHTTPURLResponse *httpResponse = (NSHTTPURLResponse *)response;
            NSString *responseString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
            
            if (httpResponse.statusCode == 200 && responseString && ([responseString containsString:@"Nicchx"] || [responseString containsString:@"momo"])) {
                // Store license key
                [[NSUserDefaults standardUserDefaults] setObject:key forKey:LICENSE_KEY_STORAGE];
                [[NSUserDefaults standardUserDefaults] setObject:key forKey:@"fluck.license.key"];
                
                // Parse live expiry from server response
                id jsonObj = [NSJSONSerialization JSONObjectWithData:data options:0 error:nil];
                if ([jsonObj isKindOfClass:[NSDictionary class]]) {
                    NSDictionary *dict = (NSDictionary *)jsonObj;
                    NSString *liveExpiry = dict[@"expiry"] ?: dict[@"expires_at"] ?: dict[@"fluck.license.expiry"];
                    if (liveExpiry && [liveExpiry isKindOfClass:[NSString class]] && liveExpiry.length > 0) {
                        [[NSUserDefaults standardUserDefaults] setObject:liveExpiry forKey:@"fluck.license.expiry"];
                        [[NSUserDefaults standardUserDefaults] setObject:liveExpiry forKey:@"external.license.expiry"];
                    }
                }
                [[NSUserDefaults standardUserDefaults] synchronize];
                
                id coreClass = (id)NSClassFromString(@"FluckAuthCore");
                if (coreClass) {
                    id sharedCore = [coreClass performSelector:NSSelectorFromString(@"shared")];
                    if (sharedCore && [sharedCore respondsToSelector:NSSelectorFromString(@"saveKey:")]) {
                        [sharedCore performSelector:NSSelectorFromString(@"saveKey:") withObject:key];
                    }
                    if (sharedCore && [sharedCore respondsToSelector:NSSelectorFromString(@"markGatePassed")]) {
                        [sharedCore performSelector:NSSelectorFromString(@"markGatePassed")];
                    }
                }
                
                [self updateStatus:@"Activated successfully! Launching..." isError:NO];
                
                dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.35 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
                    [self finishAuthentication];
                });
            } else if (httpResponse.statusCode == 503) {
                [self updateStatus:@"Application is paused by administrator." isError:YES];
            } else if (httpResponse.statusCode == 426) {
                [self updateStatus:@"Newer version detected! Please contact owner." isError:YES];
            } else if (httpResponse.statusCode == 403) {
                [self updateStatus:@"License key has expired, is revoked, or bound to another device." isError:YES];
            } else if (httpResponse.statusCode == 401) {
                [self updateStatus:@"Invalid license key. Please check your key." isError:YES];
            } else {
                [self updateStatus:@"Application is paused by administrator." isError:YES];
            }
        });
    }];
    
    [task resume];
}

- (void)finishAuthentication {
    [UIView animateWithDuration:0.3 animations:^{
        self.view.alpha = 0.0;
        self.view.transform = CGAffineTransformMakeScale(1.05, 1.05);
    } completion:^(BOOL finished) {
        UIWindow *window = GetActiveAppWindow();
        if (self.originalRootVC) {
            window.rootViewController = self.originalRootVC;
            [VIPThemeManager applyVIPThemeToViewController:self.originalRootVC];
        } else if (self.presentingViewController) {
            [self dismissViewControllerAnimated:NO completion:nil];
        }
        [self.view removeFromSuperview];
        [self removeFromParentViewController];
    }];
}

@end

#pragma mark - Live Session & Heartbeat Security Engine

@interface SessionSecurityManager : NSObject
+ (instancetype)shared;
- (void)startHeartbeatMonitor;
- (void)stopHeartbeatMonitor;
- (void)verifyLiveSessionNow;
- (void)handleSessionRevoked:(NSString *)reason;
@end

static void PresentAuthGate(void);

@implementation SessionSecurityManager {
    NSTimer *_heartbeatTimer;
    BOOL _isRevoked;
}

+ (instancetype)shared {
    static SessionSecurityManager *instance = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        instance = [[SessionSecurityManager alloc] init];
    });
    return instance;
}

- (void)startHeartbeatMonitor {
    dispatch_async(dispatch_get_main_queue(), ^{
        [self stopHeartbeatMonitor];
        self->_isRevoked = NO;
        self->_heartbeatTimer = [NSTimer scheduledTimerWithTimeInterval:60.0
                                                                 target:self
                                                               selector:@selector(heartbeatTick)
                                                               userInfo:nil
                                                                repeats:YES];
        NSLog(@"[AuthGate Security] Live session heartbeat monitor started (Interval: 60s)");
    });
}

- (void)stopHeartbeatMonitor {
    if (_heartbeatTimer) {
        [_heartbeatTimer invalidate];
        _heartbeatTimer = nil;
    }
}

- (void)heartbeatTick {
    [self verifyLiveSessionNow];
}

- (void)verifyLiveSessionNow {
    NSString *key = [[NSUserDefaults standardUserDefaults] stringForKey:LICENSE_KEY_STORAGE];
    if (!key || key.length == 0) {
        [self handleSessionRevoked:@"No active license key found."];
        return;
    }
    
    NSString *udid = [[[UIDevice currentDevice] identifierForVendor] UUIDString] ?: @"IOS-DEVICE-1";
    NSString *appVer = [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"] ?: @"1.1";
    NSString *escapedKey = [key stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    NSString *escapedUdid = [udid stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    NSString *escapedVer = [appVer stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]];
    
    NSString *urlString = [NSString stringWithFormat:@"%@?license_key=%@&udid=%@&version=%@", BACKEND_SERVER_URL, escapedKey, escapedUdid, escapedVer];
    NSURL *url = [NSURL URLWithString:urlString];
    NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
    [request setHTTPMethod:@"GET"];
    [request setTimeoutInterval:8.0];
    
    NSURLSessionDataTask *task = [[NSURLSession sharedSession] dataTaskWithRequest:request completionHandler:^(NSData * _Nullable data, NSURLResponse * _Nullable response, NSError * _Nullable error) {
        if (error || !data) {
            NSLog(@"[AuthGate Security] Heartbeat network check skipped (offline/unreachable).");
            return;
        }
        
        NSHTTPURLResponse *httpResp = (NSHTTPURLResponse *)response;
        NSString *respStr = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
        
        dispatch_async(dispatch_get_main_queue(), ^{
            if (httpResp.statusCode == 200 && respStr && ([respStr containsString:@"Nicchx"] || [respStr containsString:@"momo"])) {
                NSLog(@"[AuthGate Security] Live session heartbeat confirmed active.");
            } else if (httpResp.statusCode == 503) {
                [self handleSessionRevoked:@"Application paused by administrator."];
            } else if (httpResp.statusCode == 426) {
                [self handleSessionRevoked:@"Newer version detected! Update required."];
            } else if (httpResp.statusCode == 403) {
                [self handleSessionRevoked:@"License expired, revoked, or bound to another device."];
            } else {
                [self handleSessionRevoked:@"Session authorization rejected by server."];
            }
        });
    }];
    [task resume];
}

- (void)handleSessionRevoked:(NSString *)reason {
    if (_isRevoked) return;
    _isRevoked = YES;
    
    NSLog(@"[AuthGate Security] CRITICAL: Session Revocation Triggered: %@", reason);
    [self stopHeartbeatMonitor];
    
    // Clear saved licenses
    [[NSUserDefaults standardUserDefaults] removeObjectForKey:LICENSE_KEY_STORAGE];
    [[NSUserDefaults standardUserDefaults] removeObjectForKey:@"fluck.license.key"];
    [[NSUserDefaults standardUserDefaults] removeObjectForKey:@"external.license.expiry"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    
    // Present Lock Screen
    PresentAuthGate();
}

@end

#pragma mark - Hook & Presentation Initializers

static void InstallAuthHooks(void) {
    Class coreClass = NSClassFromString(@"FluckAuthCore");
    if (coreClass) {
        SwizzleInstance(coreClass, NSSelectorFromString(@"savedKey"), [FluckAuthCoreHook class], @selector(hooked_savedKey));
        SwizzleInstance(coreClass, NSSelectorFromString(@"packageName"), [FluckAuthCoreHook class], @selector(hooked_packageName));
        SwizzleInstance(coreClass, NSSelectorFromString(@"expiryText"), [FluckAuthCoreHook class], @selector(hooked_expiryText));
        SwizzleInstance(coreClass, NSSelectorFromString(@"gatePassed"), [FluckAuthCoreHook class], @selector(hooked_gatePassed));
        SwizzleInstance(coreClass, NSSelectorFromString(@"revokeGateWithReason:"), [FluckAuthCoreHook class], @selector(hooked_revokeGateWithReason:));
        SwizzleInstance(coreClass, NSSelectorFromString(@"revokeAndDie:label:"), [FluckAuthCoreHook class], @selector(hooked_revokeAndDie:label:));
        SwizzleInstance(coreClass, NSSelectorFromString(@"failAndDie:"), [FluckAuthCoreHook class], @selector(hooked_failAndDie:));
        SwizzleInstance(coreClass, NSSelectorFromString(@"startKeyWatchdog"), [FluckAuthCoreHook class], @selector(hooked_startKeyWatchdog));
        SwizzleInstance(coreClass, NSSelectorFromString(@"startHeartbeat"), [FluckAuthCoreHook class], @selector(hooked_startHeartbeat));
        SwizzleInstance(coreClass, NSSelectorFromString(@"startPulse"), [FluckAuthCoreHook class], @selector(hooked_startPulse));
        SwizzleInstance(coreClass, NSSelectorFromString(@"checkPackageWithCompletion:"), [FluckAuthCoreHook class], @selector(hooked_checkPackageWithCompletion:));
        NSLog(@"[AuthGate] FluckAuthCore complete runtime swizzles installed successfully");
    }
    
    Class patchClass = NSClassFromString(@"ProxyPatchBytes");
    if (patchClass) {
        SwizzleClassMethod(patchClass, NSSelectorFromString(@"bytesForPatch:"), [ProxyPatchBytesHook class], @selector(hooked_bytesForPatch:));
        SwizzleInstance(patchClass, NSSelectorFromString(@"bytesForPatch:"), [ProxyPatchBytesHook class], @selector(instance_hooked_bytesForPatch:));
        NSLog(@"[AuthGate] ProxyPatchBytes live streaming swizzles installed successfully");
    }
    
    [FFFileReplacementEngine installFileReplacementHooks];
}

static void PresentAuthGate(void) {
    dispatch_async(dispatch_get_main_queue(), ^{
        UIWindow *window = GetActiveAppWindow();
        if (!window || !window.rootViewController) {
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.1 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
                PresentAuthGate();
            });
            return;
        }
        
        UIViewController *currentRoot = window.rootViewController;
        if ([currentRoot isKindOfClass:[AuthGateViewController class]]) {
            return;
        }
        
        AuthGateViewController *authVC = [[AuthGateViewController alloc] init];
        authVC.originalRootVC = currentRoot;
        window.rootViewController = authVC;
    });
}

__attribute__((constructor))
static void AuthGateInitialize(void) {
    NSLog(@"[AuthGate] Dynamic Library Loaded Successfully");
    
    InstallAuthHooks();
    [VIPThemeManager installThemeHooks];
    
    [[NSNotificationCenter defaultCenter] addObserverForName:UIApplicationDidFinishLaunchingNotification
                                                      object:nil
                                                       queue:[NSOperationQueue mainQueue]
                                                  usingBlock:^(NSNotification * _Nonnull note) {
        PresentAuthGate();
        if ([[NSUserDefaults standardUserDefaults] stringForKey:LICENSE_KEY_STORAGE]) {
            [[SessionSecurityManager shared] startHeartbeatMonitor];
        }
    }];
}
